const ItemTableRecord*
findItemTableRecord(uint16_t itemId, bool female)
{
    const ItemTableRecord* records = female ?
        ITEM_WOMAN_RECORDS : ITEM_MAN_RECORDS;
    const int count = female ?
        ITEM_WOMAN_RECORD_COUNT : ITEM_MAN_RECORD_COUNT;
    for(int index = 0; index < count; ++index)
        if(records[index].itemId == itemId)
            return records + index;
    return 0;
}
